class C {
    public int Value;
    public C(int n) : this(second: n++, first: ++n) { Print("outer:" + n); }
    private C(int first, long second, int extra = 7) { Print("inner:" + first + ":" + second + ":" + extra); Value = first; }
    public C(string label) : this(2) => Print(label);
}
void Main() { Print(new C(3).Value); Print(new C("expression body").Value); }
